```java
Runnable task = () -> processRequest();

// Option 1: new Thread
new Thread(task).start();

// Option 2: thread pool
ExecutorService pool = Executors.newFixedThreadPool(4);
pool.submit(task);

// Option 3: run synchronously (for testing)
task.run();
```

```java
ThreadLocal<String> userContext = new ThreadLocal<>();

// Thread A sets its own value
userContext.set("user-alice");

// Thread B sets its own value
userContext.set("user-bob");

// Each thread reads its own value — isolated
System.out.println(userContext.get()); // Thread A: user-alice, Thread B: user-bob

// IMPORTANT: remove after use in thread pools!
userContext.remove();
```

```java
// Anonymous class (old)
Runnable r1 = new Runnable() {
    public void run() { System.out.println("old style"); }
};

// Lambda (modern)
Runnable r2 = () -> System.out.println("lambda");

// Method reference
Runnable r3 = MyClass::staticMethod;

// All three are equivalent — pass to Thread or ExecutorService
new Thread(r2).start();
pool.submit(r3);
```

```java
Runnable task = () -> System.out.println(Thread.currentThread().getName());

// With raw Thread
new Thread(task).start();

// With ExecutorService.execute (no return value)
ExecutorService exec = Executors.newFixedThreadPool(2);
exec.execute(task); // returns void

// With ExecutorService.submit (returns Future<?>)
Future<?> future = exec.submit(task);
future.get(); // returns null (Runnable has no result)
```
